          b: { type: 'number' },
          operation: {
            type: 'string',
            enum: ['add', 'subtract', 'multiply', 'divide'],
          },
        },
        required: ['a', 'b', 'operation'],
      },
    },
  ];
}

export async function callTool(name, args) {
  if (name !== 'calculate') {
    throw new Error(`Unknown tool: ${name}`);
  }

  // Validate required fields are present
  if (args.a === undefined || args.b === undefined || args.operation === undefined) {
    throw new Error('Missing required fields: a, b, operation');
  }

  // Reject extra fields
  const allowedKeys = new Set(['a', 'b', 'operation']);
  for (const key of Object.keys(args)) {
    if (!allowedKeys.has(key)) {
      throw new Error(`Unexpected field: ${key}`);
    }
  }

  // Validate types
  if (typeof args.a !== 'number') {
    throw new Error('Field "a" must be a number');
  }
  if (typeof args.b !== 'number') {
    throw new Error('Field "b" must be a number');
  }
  if (!VALID_OPERATIONS.has(args.operation)) {
    throw new Error(`Unsupported operation: ${args.operation}`);
  }

  const { a, b, operation } = args;

  let result;
  switch (operation) {
    case 'add':
      result = a + b;
      break;
    case 'subtract':
      result = a - b;
      break;
    case 'multiply':
      result = a * b;
      break;
    case 'divide':
      if (b === 0) {
        throw new Error('Division by zero');
      }
      result = a / b;
      break;
  }

  return {
    content: [{ type: 'text', text: String(result) }],
  };
}

